import { handleError } from '../src/ErrorHandling';

jest.mock('../src/ImageUploadService');
jest.mock('../src/ErrorHandling');

describe('UserProfileModule', () => {
  afterEach(() => {
    jest.clearAllMocks();
  });

  it('should render upload button and save changes button', () => {
    const { getByText } = render(<UserProfileModule />);
    expect(getByText('Upload Profile Picture')).toBeInTheDocument();
    expect(getByText('Save Changes')).toBeInTheDocument();
  });

  it('should validate file size before upload', async () => {
    const { getByText } = render(<UserProfileModule />);
    const fileInput = getByText('Upload Profile Picture');
    const file = new File(['large file'], 'largefile.jpg', { type: 'image/jpeg' });
    file.size = 10 * 1024 * 1024; // 10MB

    fireEvent.change(fileInput, { target: { files: [file] } });
    await waitFor(() => expect(getByText('File size exceeds the maximum limit of 5MB')).toBeInTheDocument());
  });

  it('should upload file with size less than 5MB', async () => {
    const { getByText } = render(<UserProfileModule />);
    const fileInput = getByText('Upload Profile Picture');
    const file = new File(['small file'], 'smallfile.jpg', { type: 'image/jpeg' });
    file.size = 1 * 1024 * 1024; // 1MB

    fireEvent.change(fileInput, { target: { files: [file] } });
    const saveChangesButton = getByText('Save Changes');
    fireEvent.click(saveChangesButton);

    expect(uploadProfilePicture).toHaveBeenCalledTimes(1);
    expect(uploadProfilePicture).toHaveBeenCalledWith(file);
  });

  it('should upload file with different image formats', async () => {
    const { getByText } = render(<UserProfileModule />);
    const fileInput = getByText('Upload Profile Picture');
    const pngFile = new File(['png file'], 'pngfile.png', { type: 'image/png' });
    pngFile.size = 1 * 1024 * 1024; // 1MB
    const jpgFile = new File(['jpg file'], 'jpgfile.jpg', { type: 'image/jpeg' });
    jpgFile.size = 1 * 1024 * 1024; // 1MB
    const gifFile = new File(['gif file'], 'giffile.gif', { type: 'image/gif' });
    gifFile.size = 1 * 1024 * 1024; // 1MB

    fireEvent.change(fileInput, { target: { files: [pngFile] } });
    const saveChangesButton = getByText('Save Changes');
    fireEvent.click(saveChangesButton);
    expect(uploadProfilePicture).toHaveBeenCalledTimes(1);
    expect(uploadProfilePicture).toHaveBeenCalledWith(pngFile);

    fireEvent.change(fileInput, { target: { files: [jpgFile] } });
    fireEvent.click(saveChangesButton);
    expect(uploadProfilePicture).toHaveBeenCalledTimes(2);
    expect(uploadProfilePicture).toHaveBeenCalledWith(jpgFile);

    fireEvent.change(fileInput, { target: { files: [gifFile] } });
    fireEvent.click(saveChangesButton);
    expect(uploadProfilePicture).toHaveBeenCalledTimes(3);
    expect(uploadProfilePicture).toHaveBeenCalledWith(gifFile);
  });

  it('should handle upload error', async () => {
    const { getByText } = render(<UserProfileModule />);
    const fileInput = getByText('Upload Profile Picture');
    const file = new File(['small file'], 'smallfile.jpg', { type: 'image/jpeg' });
    file.size = 1 * 1024 * 1024; // 1MB

    uploadProfilePicture.mockRejectedValue(new Error('Upload failed'));

    fireEvent.change(fileInput, { target: { files: [file] } });
    const saveChangesButton = getByText('Save Changes');
    fireEvent.click(saveChangesButton);

    await waitFor(() => expect(handleError).toHaveBeenCalledTimes(1));
  });

  it('should not upload file without selecting a file', async () => {
    const { getByText } = render(<UserProfileModule />);
    const saveChangesButton = getByText('Save Changes');
    fireEvent.click(saveChangesButton);

    expect(uploadProfilePicture).not.toHaveBeenCalled();
  });
});
